/** A plain play triangle. START TIMER. Nothing in `INBOX/` was this simple. */
export function PlayTriangleIcon({ className = 'w-4 h-4' }: { className?: string }) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      fill="currentColor"
      aria-hidden="true"
      className={`shrink-0 ${className}`}
    >
      <path d="M8 5v14l11-7z" />
    </svg>
  );
}

/**
 * A plain square. STOP TIMER. Deliberately not the app's existing `StopIcon`
 * (a raised palm inside a broken ring, `INBOX/stop.svg`, used for Stop Sharing
 * in LiveShareView) — that reads as "halt an action," and this button needs
 * the classic media-stop shape instead.
 */
export function StopSquareIcon({ className = 'w-4 h-4' }: { className?: string }) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      fill="currentColor"
      aria-hidden="true"
      className={`shrink-0 ${className}`}
    >
      <path d="M6 6h12v12H6z" />
    </svg>
  );
}

/**
 * Two bars: the classic media pause. What the middle key on a running timer
 * wears, because that is what it does — the clock stops where it is and Start
 * Timer picks it up again. The square beside it says the run is over and
 * something has to be reset, which is Reset's job on the same row.
 */
export function PauseIcon({ className = 'w-4 h-4' }: { className?: string }) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      fill="currentColor"
      aria-hidden="true"
      className={`shrink-0 ${className}`}
    >
      <path d="M7 5h3.2v14H7zm6.8 0H17v14h-3.2z" />
    </svg>
  );
}
